//! The Row-Level Security contract of the event-sourced SaaS service:
//! tenant keys, the access policy, the generated DDL and its golden files.
//! The behaviour of the DDL against PostgreSQL is tested in
//! `edomata-saas-sqlx` (`tests/rls.rs`).
//!
//! The golden files have no Scala counterpart (the Scala SaaS module has no
//! RLS for event-sourced tables): they are generated by this crate. Bless
//! them after an intended change with `EDOMATA_BLESS_GOLDEN=1 cargo test -p
//! edomata-saas --test rls`.

use std::path::PathBuf;

use edomata_saas::{
    AccessMode, PGNaming, RlsAccessPolicy, RlsPolicyError, SaaSPGSchema, TENANT_SEPARATOR,
    TenantId, TenantKey, TenantKeyError, validate_tenant_key,
};

fn policy() -> RlsAccessPolicy<TenantId> {
    RlsAccessPolicy::with_prefix("app").unwrap()
}

fn prefixed(ns: &str) -> PGNaming {
    PGNaming::prefixed_str(ns).unwrap()
}

fn schema(ns: &str) -> PGNaming {
    PGNaming::schema_str(ns).unwrap()
}

// --- tenant keys ------------------------------------------------------------

#[test]
fn a_tenant_containing_the_separator_is_refused() {
    assert_eq!(TENANT_SEPARATOR, '/');
    assert_eq!(
        validate_tenant_key("a/b"),
        Err(TenantKeyError::ContainsSeparator)
    );
    assert_eq!(
        validate_tenant_key("/"),
        Err(TenantKeyError::ContainsSeparator)
    );
    assert_eq!(
        validate_tenant_key("acme/"),
        Err(TenantKeyError::ContainsSeparator)
    );
    let policy = policy();
    assert_eq!(
        policy.tenant_access(&TenantId::new("a/b")).unwrap_err(),
        TenantKeyError::ContainsSeparator
    );
    assert_eq!(
        policy.scoped_id(&TenantId::new("a/b"), "x").unwrap_err(),
        TenantKeyError::ContainsSeparator
    );
}

#[test]
fn an_empty_or_nul_tenant_is_refused() {
    assert_eq!(validate_tenant_key(""), Err(TenantKeyError::Empty));
    assert_eq!(
        validate_tenant_key("a\0b"),
        Err(TenantKeyError::ContainsNul)
    );
    assert!(policy().tenant_access(&TenantId::new("")).is_err());
    assert!(!TenantKeyError::Empty.to_string().is_empty());
}

#[test]
fn tenant_key_types_are_the_implementations_choice() {
    struct Org(u32);
    impl TenantKey for Org {
        fn tenant_key(&self) -> String {
            format!("org{}", self.0)
        }
    }
    let policy: RlsAccessPolicy<Org> = RlsAccessPolicy::with_prefix("app").unwrap();
    let access = policy.tenant_access(&Org(42)).unwrap();
    assert_eq!(access.tenant(), Some("org42"));
    assert_eq!(policy.scoped_id(&Org(42), "o-1").unwrap(), "org42/o-1");
}

// --- the policy and the accesses ----------------------------------------------

#[test]
fn the_three_modes_are_three_distinct_roles() {
    let policy = policy();
    assert_eq!(policy.role(AccessMode::Tenant), "app_tenant");
    assert_eq!(policy.role(AccessMode::System), "app_system");
    assert_eq!(policy.role(AccessMode::Inspection), "app_inspection");
    assert_eq!(policy.tenant_setting(), "app.tenant_id");

    let tenant = policy.tenant_access(&TenantId::new("acme")).unwrap();
    assert_eq!(tenant.set_role_statement(), "SET LOCAL ROLE app_tenant");
    assert_eq!(tenant.tenant_setting_value(), "acme");
    // System and inspection carry no tenant: the setting is the empty
    // string, which matches no row of the tenant policy.
    assert_eq!(policy.system_access().tenant(), None);
    assert_eq!(policy.system_access().tenant_setting_value(), "");
    assert_eq!(
        policy.inspection_access().set_role_statement(),
        "SET LOCAL ROLE app_inspection"
    );
}

#[test]
fn a_policy_refuses_names_that_could_inject_sql_or_collide() {
    assert!(matches!(
        RlsAccessPolicy::<TenantId>::new("a; drop table x", "s", "i", "app.t"),
        Err(RlsPolicyError::InvalidIdentifier(_))
    ));
    assert!(matches!(
        RlsAccessPolicy::<TenantId>::new("Tenant", "s", "i", "app.t"),
        Err(RlsPolicyError::InvalidIdentifier(_))
    ));
    assert!(matches!(
        RlsAccessPolicy::<TenantId>::new("t", "s", "i", "no_dot"),
        Err(RlsPolicyError::InvalidSetting(_))
    ));
    assert!(matches!(
        RlsAccessPolicy::<TenantId>::new("t", "s", "i", "app.t'; --"),
        Err(RlsPolicyError::InvalidSetting(_))
    ));
    assert_eq!(
        RlsAccessPolicy::<TenantId>::new("same", "same", "i", "app.t"),
        Err(RlsPolicyError::DuplicateRole("same".to_string()))
    );
    assert!(RlsAccessPolicy::<TenantId>::with_prefix("Bad Prefix").is_err());
    assert!(SaaSPGSchema::rls_memberships(&policy(), "x; y", &[AccessMode::Tenant]).is_err());
}

// --- the DDL ------------------------------------------------------------------

fn es_ddl(naming: &PGNaming) -> Vec<String> {
    SaaSPGSchema::eventsourcing_rls(naming, "jsonb", "jsonb", "jsonb", &policy())
}

#[test]
fn every_event_sourced_table_has_a_generated_tenant_column() {
    let ddl = es_ddl(&prefixed("app"));
    for (table, source) in [
        ("app_journal", "stream"),
        ("app_outbox", "stream"),
        ("app_commands", "id"),
        ("app_snapshots", "id"),
    ] {
        let create = ddl
            .iter()
            .find(|s| s.starts_with(&format!("CREATE TABLE IF NOT EXISTS {table} (")))
            .unwrap_or_else(|| panic!("no CREATE TABLE for {table}"));
        assert!(
            create.contains(&format!(
                "tenant_id text GENERATED ALWAYS AS (CASE WHEN position('/' in {source}) > 1 THEN split_part({source}, '/', 1) END) STORED NOT NULL"
            )),
            "{table}: {create}"
        );
    }
}

#[test]
fn rls_is_enabled_and_forced_on_every_table() {
    let ddl = es_ddl(&prefixed("app"));
    for table in ["app_journal", "app_outbox", "app_commands", "app_snapshots"] {
        assert!(ddl.contains(&format!("ALTER TABLE {table} ENABLE ROW LEVEL SECURITY;")));
        assert!(ddl.contains(&format!("ALTER TABLE {table} FORCE ROW LEVEL SECURITY;")));
    }
}

#[test]
fn the_tenant_policy_has_using_and_with_check_and_denies_a_missing_tenant() {
    for statement in es_ddl(&prefixed("app"))
        .iter()
        .filter(|s| s.starts_with("CREATE POLICY") && s.contains("_tenant_policy"))
    {
        let check = "tenant_id = NULLIF(current_setting('app.tenant_id', true), '')";
        assert!(
            statement.contains(&format!("USING ({check})")),
            "{statement}"
        );
        assert!(
            statement.contains(&format!("WITH CHECK ({check})")),
            "{statement}"
        );
        assert!(statement.contains("TO app_tenant"), "{statement}");
    }
    let all = es_ddl(&prefixed("app")).join("\n");
    // Never the one-argument form (it raises instead of denying) and never
    // a session variable as a mode switch.
    assert!(!all.contains("current_setting('app.tenant_id')"));
    assert!(!all.contains("mode"));
    assert_eq!(all.matches("CREATE POLICY").count(), 12);
}

#[test]
fn the_inspection_role_is_select_only_and_the_system_role_goes_through_its_own_policy() {
    let ddl = es_ddl(&prefixed("app"));
    for table in ["app_journal", "app_outbox", "app_commands", "app_snapshots"] {
        assert!(ddl.contains(&format!("GRANT SELECT ON {table} TO app_inspection;")));
        assert!(ddl.contains(&format!(
            "CREATE POLICY {table}_inspection_policy ON {table} FOR SELECT TO app_inspection\n  USING (true);"
        )));
        assert!(ddl.contains(&format!(
            "CREATE POLICY {table}_system_policy ON {table} FOR ALL TO app_system\n  USING (true)\n  WITH CHECK (true);"
        )));
    }
    // The tenant role never updates or deletes the append-only tables.
    assert!(ddl.contains(&"GRANT SELECT, INSERT ON app_journal TO app_tenant;".to_string()));
    assert!(
        !ddl.iter()
            .any(|s| s.contains("DELETE") && s.contains("app_tenant"))
    );
}

#[test]
fn schema_mode_grants_usage_on_the_schema_and_quotes_it() {
    let ddl = es_ddl(&schema("app"));
    assert_eq!(ddl[0], "CREATE SCHEMA IF NOT EXISTS \"app\";");
    assert!(ddl.contains(
        &"GRANT USAGE ON SCHEMA \"app\" TO app_tenant, app_system, app_inspection;".to_string()
    ));
    assert!(ddl.contains(&"ALTER TABLE \"app\".journal FORCE ROW LEVEL SECURITY;".to_string()));
    assert!(ddl.contains(
        &"GRANT USAGE ON SEQUENCE \"app\".journal_seqnr_seq TO app_tenant, app_system;".to_string()
    ));
    // Prefix mode needs neither.
    assert!(
        !es_ddl(&prefixed("app"))
            .iter()
            .any(|s| s.contains("ON SCHEMA"))
    );
}

#[test]
fn the_table_statements_are_idempotent_and_the_policies_are_not() {
    let tables =
        SaaSPGSchema::eventsourcing_rls_tables(&prefixed("app"), "jsonb", "jsonb", "jsonb");
    assert!(
        tables
            .iter()
            .all(|s| s.contains("IF NOT EXISTS") && !s.contains("POLICY"))
    );
    let all = es_ddl(&prefixed("app"));
    assert!(all.starts_with(&tables));
    assert!(
        all.iter()
            .filter(|s| s.starts_with("CREATE POLICY"))
            .all(|s| !s.contains("IF NOT EXISTS"))
    );
}

#[test]
fn roles_and_memberships() {
    let policy = policy();
    let roles = SaaSPGSchema::rls_roles(&policy);
    assert_eq!(roles.len(), 3);
    assert!(roles.iter().all(|s| {
        s.contains("NOLOGIN") && s.contains("NOSUPERUSER") && s.contains("NOBYPASSRLS")
    }));
    assert_eq!(
        SaaSPGSchema::rls_memberships(
            &policy,
            "app_job",
            &[AccessMode::System, AccessMode::Inspection]
        )
        .unwrap(),
        vec![
            "GRANT app_system TO app_job;".to_string(),
            "GRANT app_inspection TO app_job;".to_string()
        ]
    );
}

// --- golden files -------------------------------------------------------------

const NAMINGS: [(&str, &str); 3] = [
    ("schema", "catalog"),
    ("prefixed", "catalog"),
    ("schema", "Shop_v2$"),
];
const TYPES: [(&str, &str, &str, &str); 4] = [
    ("jsonb", "jsonb", "jsonb", "jsonb"),
    ("json", "json", "json", "json"),
    ("bytea", "bytea", "bytea", "bytea"),
    ("mixed", "bytea", "json", "jsonb"),
];

fn golden_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/golden")
}

fn check_golden(file: &str, actual: String) {
    let path = golden_dir().join(file);
    if std::env::var_os("EDOMATA_BLESS_GOLDEN").is_some() {
        std::fs::write(&path, &actual).unwrap();
        return;
    }
    let expected = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("missing golden file {}: {e}", path.display()));
    assert_eq!(actual, expected, "golden mismatch for {file}");
}

#[test]
fn event_sourced_rls_ddl_matches_the_golden_files() {
    let policy = policy();
    for (kind, ns) in NAMINGS {
        let naming = match kind {
            "schema" => schema(ns),
            _ => prefixed(ns),
        };
        for (label, event, notification, snapshot) in TYPES {
            let file = format!(
                "saas_es_rls_{kind}_{}_{label}.sql",
                ns.to_lowercase().replace('$', "_")
            );
            let actual =
                SaaSPGSchema::eventsourcing_rls(&naming, event, notification, snapshot, &policy)
                    .join("\n")
                    + "\n";
            check_golden(&file, actual);
        }
    }
}

#[test]
fn roles_and_memberships_match_the_golden_file() {
    let policy = policy();
    let mut statements = SaaSPGSchema::rls_roles(&policy);
    for (login, modes) in [
        ("app_web", vec![AccessMode::Tenant]),
        ("app_relay", vec![AccessMode::System]),
        ("app_agent", vec![AccessMode::Inspection]),
    ] {
        statements.extend(SaaSPGSchema::rls_memberships(&policy, login, &modes).unwrap());
    }
    check_golden("saas_es_rls_roles.sql", statements.join("\n") + "\n");
}

#[test]
fn every_event_sourced_rls_golden_file_is_covered() {
    let count = std::fs::read_dir(golden_dir())
        .unwrap()
        .filter(|e| {
            e.as_ref()
                .unwrap()
                .file_name()
                .to_string_lossy()
                .starts_with("saas_es_rls_")
        })
        .count();
    assert_eq!(count, NAMINGS.len() * TYPES.len() + 1);
}
